import{_ as d,o as t,c as a,ag as o}from"./chunks/framework.DaCm-iTo.js";const h=JSON.parse('{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/codex/commands.md","filePath":"modules/codex/commands.md","lastUpdated":null}'),c={name:"modules/codex/commands.md"};function n(s,e,r,l,i,p){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to &quot;命令与权限&quot;">​</a></h1><p>EmakiCodex 的主命令是 <code>/codex</code>，别名为 <code>/ecodex</code>。文档示例统一使用 <code>/codex</code>。</p><p>Paper 命令入口本身要求 <code>emakicodex.use</code>；管理类子命令还会继续检查对应的 reload、debug 或 admin 权限。</p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to &quot;命令列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/codex</code></td><td><code>emakicodex.use</code></td><td>显示帮助。</td></tr><tr><td><code>/codex help</code></td><td><code>emakicodex.use</code></td><td>显示帮助。</td></tr><tr><td><code>/codex reload</code></td><td><code>emakicodex.reload</code> 或 <code>emakicodex.admin</code></td><td>重载配置、语言、成就页，重新注册 Advancement，并尝试向在线玩家重推。</td></tr><tr><td><code>/codex grant &lt;player&gt; &lt;advId&gt;</code></td><td><code>emakicodex.admin</code></td><td>授予在线玩家一个 Codex 节点。</td></tr><tr><td><code>/codex revoke &lt;player&gt; &lt;advId&gt;</code></td><td><code>emakicodex.admin</code></td><td>撤销在线玩家一个 Codex 节点。</td></tr><tr><td><code>/codex debug ...</code></td><td><code>emakicodex.debug</code> 或 <code>emakicodex.admin</code></td><td>管理 <code>advancement</code> debug 模块。具体子命令由 CoreLib DebugCommand 提供。</td></tr></tbody></table><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/codex</span></span>
<span class="line"><span>/codex help</span></span>
<span class="line"><span>/codex reload</span></span>
<span class="line"><span>/codex grant Steve example/first_step</span></span>
<span class="line"><span>/codex grant Steve emakicodex:example/challenge</span></span>
<span class="line"><span>/codex revoke Steve example/first_step</span></span>
<span class="line"><span>/codex debug advancement on</span></span>
<span class="line"><span>/codex debug advancement off</span></span></code></pre></div><p><code>grant</code> 与 <code>revoke</code> 的目标玩家必须在线，因为当前实现使用在线玩家名精确匹配。<code>advId</code> 支持两种写法：</p><table tabindex="0"><thead><tr><th>写法</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>page/node</code></td><td><code>example/first_step</code></td><td>推荐给服主使用的短写。</td></tr><tr><td>完整 NamespacedKey</td><td><code>emakicodex:example/first_step</code></td><td>与底层原版 Advancement key 一致。</td></tr></tbody></table><h2 id="reload-行为" tabindex="-1">reload 行为 <a class="header-anchor" href="#reload-行为" aria-label="Permalink to &quot;reload 行为&quot;">​</a></h2><p><code>/codex reload</code> 会执行以下工作：</p><ol><li>释放缺失的默认资源，受 <code>config.yml &gt; release_default_data</code> 控制。</li><li>重新读取 <code>config.yml</code>、<code>lang/*.yml</code> 与 <code>advancements/*.yml</code>。</li><li>移除并重新注册 EmakiCodex 命名空间下的动态 Advancement。</li><li>如果 PacketEvents 可用，向在线玩家重推成就树；否则在线玩家可能需要重新登录才能看到界面变化。</li></ol><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to &quot;权限节点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>覆盖范围</th></tr></thead><tbody><tr><td><code>emakicodex.use</code></td><td><code>true</code></td><td>使用 <code>/codex</code> 命令入口与帮助。</td></tr><tr><td><code>emakicodex.reload</code></td><td><code>op</code></td><td>使用 <code>/codex reload</code>。可被 <code>emakicodex.admin</code> 代替。</td></tr><tr><td><code>emakicodex.debug</code></td><td><code>op</code></td><td>使用 <code>/codex debug ...</code>。可被 <code>emakicodex.admin</code> 代替。</td></tr><tr><td><code>emakicodex.admin</code></td><td><code>op</code></td><td>使用授予、撤销等管理命令，并可代替 reload/debug 专用权限。</td></tr></tbody></table><p>常见 LuckPerms 示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/lp group default permission set emakicodex.use true</span></span>
<span class="line"><span>/lp group admin permission set emakicodex.admin true</span></span>
<span class="line"><span>/lp group admin permission set emakicodex.reload true</span></span>
<span class="line"><span>/lp group admin permission set emakicodex.debug true</span></span></code></pre></div><h2 id="常见失败原因" tabindex="-1">常见失败原因 <a class="header-anchor" href="#常见失败原因" aria-label="Permalink to &quot;常见失败原因&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>说明</th></tr></thead><tbody><tr><td><code>Player not found</code></td><td><code>grant</code> / <code>revoke</code> 的目标玩家不在线，或玩家名不完全匹配。</td></tr><tr><td><code>Advancement ... 未注册或状态无变化</code></td><td>成就 ID 写错、页面未成功加载，或授予/撤销时玩家当前进度没有变化。</td></tr><tr><td>在线玩家看不到 reload 后的新成就树</td><td>未安装 PacketEvents 或重推失败时，在线玩家需要重新登录。</td></tr><tr><td>节点坐标不生效</td><td>需要安装 PacketEvents，并开启 <code>advancement.packet-coordinates: true</code>。</td></tr></tbody></table>`,18)])])}const x=d(c,[["render",n]]);export{h as __pageData,x as default};
